CREATE TABLE `cashier_sessions` (`id` VARCHAR(191) NOT NULL, `branch_id` VARCHAR(191) NOT NULL, `cashier_id` VARCHAR(191) NOT NULL, `opening_balance` DECIMAL(18,4) NOT NULL, `closing_balance` DECIMAL(18,4) NULL, `expected_balance` DECIMAL(18,4) NULL, `status` ENUM('OPEN','CLOSED') NOT NULL DEFAULT 'OPEN', `opened_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `closed_at` DATETIME(3) NULL, PRIMARY KEY (`id`), INDEX `cashier_sessions_cashier_id_status_idx` (`cashier_id`,`status`), INDEX `cashier_sessions_branch_id_opened_at_idx` (`branch_id`,`opened_at`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `cashier_transactions` (`id` VARCHAR(191) NOT NULL, `session_id` VARCHAR(191) NOT NULL, `actor_id` VARCHAR(191) NOT NULL, `approved_by_id` VARCHAR(191) NULL, `original_transaction_id` VARCHAR(191) NULL, `journal_entry_id` VARCHAR(191) NULL, `type` ENUM('CASH_IN','CASH_OUT','RECEIPT','PAYMENT_VOUCHER','REVERSAL') NOT NULL, `status` ENUM('POSTED','REVERSED') NOT NULL DEFAULT 'POSTED', `amount` DECIMAL(18,4) NOT NULL, `payment_method` ENUM('CASH','CARD','BANK_TRANSFER','OTHER') NOT NULL, `reason` VARCHAR(500) NULL, `source_type` VARCHAR(80) NULL, `source_id` VARCHAR(120) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `cashier_transactions_session_id_created_at_idx` (`session_id`,`created_at`), INDEX `cashier_transactions_source_type_source_id_idx` (`source_type`,`source_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `cashier_receipts` (`id` VARCHAR(191) NOT NULL, `receipt_no` VARCHAR(60) NOT NULL, `session_id` VARCHAR(191) NOT NULL, `transaction_id` VARCHAR(191) NOT NULL, `created_by_id` VARCHAR(191) NOT NULL, `customer_id` VARCHAR(191) NULL, `amount` DECIMAL(18,4) NOT NULL, `payment_method` ENUM('CASH','CARD','BANK_TRANSFER','OTHER') NOT NULL, `source_type` VARCHAR(80) NULL, `source_id` VARCHAR(120) NULL, `status` ENUM('POSTED','REVERSED') NOT NULL DEFAULT 'POSTED', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `cashier_receipts_receipt_no_key` (`receipt_no`), UNIQUE INDEX `cashier_receipts_transaction_id_key` (`transaction_id`), INDEX `cashier_receipts_session_id_created_at_idx` (`session_id`,`created_at`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `payment_vouchers` (`id` VARCHAR(191) NOT NULL, `voucher_no` VARCHAR(60) NOT NULL, `session_id` VARCHAR(191) NOT NULL, `transaction_id` VARCHAR(191) NOT NULL, `created_by_id` VARCHAR(191) NOT NULL, `payee` VARCHAR(160) NOT NULL, `amount` DECIMAL(18,4) NOT NULL, `payment_method` ENUM('CASH','CARD','BANK_TRANSFER','OTHER') NOT NULL, `reason` VARCHAR(500) NOT NULL, `source_type` VARCHAR(80) NULL, `source_id` VARCHAR(120) NULL, `status` ENUM('POSTED','REVERSED') NOT NULL DEFAULT 'POSTED', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `payment_vouchers_voucher_no_key` (`voucher_no`), UNIQUE INDEX `payment_vouchers_transaction_id_key` (`transaction_id`), INDEX `payment_vouchers_session_id_created_at_idx` (`session_id`,`created_at`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `daily_cashier_closings` (`id` VARCHAR(191) NOT NULL, `session_id` VARCHAR(191) NOT NULL, `branch_id` VARCHAR(191) NOT NULL, `closing_date` DATE NOT NULL, `expected_amount` DECIMAL(18,4) NOT NULL, `actual_amount` DECIMAL(18,4) NOT NULL, `variance` DECIMAL(18,4) NOT NULL, `status` ENUM('OPEN','COMPLETED') NOT NULL DEFAULT 'COMPLETED', `notes` VARCHAR(500) NULL, `created_by_id` VARCHAR(191) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `daily_cashier_closings_session_id_key` (`session_id`), INDEX `daily_cashier_closings_branch_id_closing_date_idx` (`branch_id`,`closing_date`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `cashier_sessions` ADD CONSTRAINT `cashier_sessions_branch_id_fkey` FOREIGN KEY (`branch_id`) REFERENCES `branches`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `cashier_sessions_cashier_id_fkey` FOREIGN KEY (`cashier_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `cashier_transactions` ADD CONSTRAINT `cashier_transactions_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `cashier_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `cashier_transactions_actor_id_fkey` FOREIGN KEY (`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `cashier_transactions_approved_by_id_fkey` FOREIGN KEY (`approved_by_id`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT `cashier_transactions_original_transaction_id_fkey` FOREIGN KEY (`original_transaction_id`) REFERENCES `cashier_transactions`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `cashier_receipts` ADD CONSTRAINT `cashier_receipts_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `cashier_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `cashier_receipts_transaction_id_fkey` FOREIGN KEY (`transaction_id`) REFERENCES `cashier_transactions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `cashier_receipts_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `cashier_receipts_customer_id_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `payment_vouchers` ADD CONSTRAINT `payment_vouchers_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `cashier_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `payment_vouchers_transaction_id_fkey` FOREIGN KEY (`transaction_id`) REFERENCES `cashier_transactions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `payment_vouchers_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `daily_cashier_closings` ADD CONSTRAINT `daily_cashier_closings_session_id_fkey` FOREIGN KEY (`session_id`) REFERENCES `cashier_sessions`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `daily_cashier_closings_branch_id_fkey` FOREIGN KEY (`branch_id`) REFERENCES `branches`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, ADD CONSTRAINT `daily_cashier_closings_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
